"""VERA — AI Compliance Co-Pilot.Validates materials test results against YAML compliance templates,explains failures, and exports a report."""import ioimport jsonimport osfrom pathlib import Pathfrom typing import Dict, Listimport pandas as pdimport streamlit as stimport yamlst.set_page_config(page_title="VERA — AI Compliance Co-Pilot", layout="wide")from src import providerfrom src.io_utils import load_table, previewfrom src.llm import explain_specimenfrom src.mapper import suggest_mapping_fuzzy, suggest_mapping_llmfrom src.provider import LLMUnavailable, complete, complete_jsonfrom src.report import make_pdffrom src.rules import eval_checkfrom src.theme import inject_theme, mastheadinject_theme()# ----------------------------------------------------------------------------# Free-tier policy# ----------------------------------------------------------------------------FREE_ANALYSES = 3          # AI-assisted files per IPMAX_EXPLANATIONS = 5       # explanations per analysisGLOBAL_CALL_CAP = 200      # hard ceiling on calls funded by the house keyKEY_URL = "https://console.anthropic.com/settings/keys"@st.cache_resourcedef _usage_store() -> dict:    """Server-side counters. Shared across sessions, cleared on app restart."""    return {"by_ip": {}, "global_calls": 0}def client_ip() -> str:    try:        ip = st.context.ip_address    except Exception:        ip = None    return ip or "local"def _house_key() -> str:    try:        return str(st.secrets.get("ANTHROPIC_API_KEY", "") or "")    except Exception:        return ""# Make the house key visible to provider unless the visitor supplied their own.if not st.session_state.get("api_key"):    hk = _house_key()    if hk and not os.environ.get("ANTHROPIC_API_KEY"):        os.environ["ANTHROPIC_API_KEY"] = hkdef visitor_key_set() -> bool:    return bool(st.session_state.get("api_key"))def analyses_left() -> int:    used = _usage_store()["by_ip"].get(client_ip(), 0)    return max(0, FREE_ANALYSES - used)def global_exhausted() -> bool:    return _usage_store()["global_calls"] >= GLOBAL_CALL_CAPdef can_use_ai() -> bool:    if visitor_key_set():        return True    if not provider.get_api_key():        return False    return not global_exhausted() and analyses_left() > 0def record_call(n: int = 1) -> None:    if not visitor_key_set():        _usage_store()["global_calls"] += ndef record_analysis() -> None:    if visitor_key_set():        return    store = _usage_store()    ip = client_ip()    store["by_ip"][ip] = store["by_ip"].get(ip, 0) + 1@st.dialog("Use your own API key")def key_dialog():    st.write(        "You've used the free analyses on this app's shared key. "        "Add your own Anthropic key to keep going. It stays in this browser "        "session only, is never saved, and is not visible to anyone else."    )    st.markdown(f"Create a key at [console.anthropic.com]({KEY_URL}). "                "Expect well under a cent per file.")    k = st.text_input("Anthropic API key", type="password",                      placeholder="sk-ant-...")    c1, c2 = st.columns(2)    with c1:        if st.button("Save and continue", use_container_width=True):            if k.strip().startswith("sk-ant-"):                st.session_state.api_key = k.strip()                st.rerun()            else:                st.error("That doesn't look like an Anthropic key.")    with c2:        if st.button("Continue without AI", use_container_width=True):            st.session_state.ai_declined = True            st.rerun()def ai_enabled() -> bool:    """True when an AI call is permitted right now."""    if st.session_state.get("ai_declined") and not visitor_key_set():        return False    return can_use_ai()# ----------------------------------------------------------------------------# Template handling# ----------------------------------------------------------------------------def parse_generated_yaml(yaml_text: str) -> dict:    """Parse LLM-produced YAML, tolerating fences and a wrapper key."""    import re    yt = yaml_text.strip()    fence = re.search(r"```(?:yaml)?\s*([\s\S]*?)```", yt, flags=re.IGNORECASE)    if fence:        yt = fence.group(1).strip()    tmpl = yaml.safe_load(yt)    if not isinstance(tmpl, dict):        raise ValueError("YAML must be a mapping at the top level.")    if isinstance(tmpl.get("compliance_rules"), dict):        tmpl = tmpl["compliance_rules"]    tmpl.setdefault("standard_id", "GENERATED")    tmpl.setdefault("version", "1.0")    tmpl.setdefault("units", {})    if isinstance(tmpl.get("units"), dict):        tmpl["units"] = {k: str(v) for k, v in tmpl["units"].items()}    checks = tmpl.get("checks", [])    if not isinstance(checks, list) or not checks:        raise ValueError("No checks[] found.")    for c in checks:        if "op" not in c or "metric" not in c:            raise ValueError("Each check must include metric and op.")        if "unit" in c:            c["unit"] = str(c["unit"])        for field in ("value", "min", "max"):            if field in c and isinstance(c[field], str):                try:                    c[field] = float(c[field])                except ValueError:                    pass    tmpl["checks"] = checks    return tmpl@st.cache_data(show_spinner=False)def cached_mapping(headers: tuple, metrics: tuple, key_fp: str):    return suggest_mapping_llm(list(headers), list(metrics))@st.cache_data(show_spinner=False)def cached_units(sample_json: str, tpl_units_json: str,                 metrics: tuple, key_fp: str) -> Dict[str, str]:    """Infer units from header names and sample values."""    tpl_units = json.loads(tpl_units_json)    fallback = {m: tpl_units.get(m, "") for m in metrics}    system = ("Infer measurement units for each metric from header names and "              "sample numeric values. Prefer SI units such as MPa, GPa, %, mm/min. "              "Return JSON only.")    user = (f"Template default units: {tpl_units_json}\n"            f"Samples: {sample_json}\n"            'Return a JSON object with one key "units", mapping each metric '            "name to a unit string.")    try:        obj = complete_json(system, user, max_tokens=250)    except LLMUnavailable:        return fallback    units = obj.get("units", {}) if isinstance(obj, dict) else {}    return {m: (units.get(m) or tpl_units.get(m, "")) for m in metrics}@st.cache_data(show_spinner=False)def _load_playbook() -> dict:    p = Path("templates/remediation_playbook.yaml")    if p.exists():        with open(p, "r", encoding="utf-8") as f:            return yaml.safe_load(f) or {}    return {"rules": []}def _extract_failing_metrics(rationale: str) -> List[str]:    fails = []    if not rationale:        return fails    for seg in rationale.split(";"):        seg = seg.strip()        if not seg:            continue        metric = seg.split()[0]        if any(k in seg.lower() for k in ("fail", "missing", "error")):            fails.append(metric)    return list(dict.fromkeys(fails))def enrich_with_playbook(row: pd.Series, base_text: str) -> str:    playbook = _load_playbook()    failing = _extract_failing_metrics(row.get("rationale", ""))    if not failing or not playbook.get("rules"):        return base_text    tips: List[str] = []    for rule in playbook["rules"]:        m = rule.get("when_metric")        if m and any(m == fm or m in fm for fm in failing):            tips.extend(rule.get("suggestions", []))    if not tips:        return base_text    return (base_text.rstrip() + "\n\nAdditional tips:\n- "            + "\n- ".join(tips[:2]))# ----------------------------------------------------------------------------# Session defaults# ----------------------------------------------------------------------------_defaults = {    "df": None, "mapping": {}, "units_map": {}, "results_df": None,    "explanations": {}, "template_override": None, "last_filename": None,    "source_bytes": None, "generated_yaml": None, "analysis_counted": False,    "api_key": "", "ai_declined": False,}for k, v in _defaults.items():    st.session_state.setdefault(k, v)def key_fingerprint() -> str:    k = provider.get_api_key()    return (k[-6:] if k else "none")# ----------------------------------------------------------------------------# Masthead and header strip# ----------------------------------------------------------------------------masthead("VERA", "Validation &amp; Explanation for Regulatory Assurance")template_files = [p for p in Path("templates").glob("*.yaml")                  if p.name != "remediation_playbook.yaml"]template_names = [p.name for p in template_files]if not template_names:    st.error("No templates found. Add YAML files to the templates folder.")    st.stop()h1, h2, h3, h4 = st.columns([1.5, 1.4, 2.2, 1.1])with h1:    if st.session_state.template_override:        st.markdown("**Standard**")        ov = st.session_state.template_override        st.write(f"{ov.get('standard_id')} v{ov.get('version')} (generated)")        if st.button("Revert to file template"):            st.session_state.template_override = None            st.rerun()        tpl_choice = None        template = ov    else:        tpl_choice = st.selectbox("Standard", template_names, index=0)        with open(Path("templates") / tpl_choice, "r", encoding="utf-8") as f:            template = yaml.safe_load(f)required_metrics = [c["metric"] for c in template.get("checks", [])]required_meta = template.get("metadata_required", [])std_id = template.get("standard_id", "STD")std_ver = template.get("version", "1.0")tpl_units = template.get("units", {})with h2:    st.markdown("**Version**")    st.write(f"{std_ver}")    st.caption(f"{len(template.get('checks', []))} checks")with h3:    st.markdown("**Required metrics**")    st.write(", ".join(required_metrics) or "none")    if required_meta:        st.caption("Metadata: " + ", ".join(required_meta))with h4:    st.markdown("**AI credits**")    if visitor_key_set():        st.write("Your own key")        if st.button("Remove key"):            st.session_state.api_key = ""            st.rerun()    elif not provider.get_api_key():        st.write("Off")        st.caption("No key configured")    elif global_exhausted():        st.write("Shared pool spent")        if st.button("Add your key"):            key_dialog()    else:        st.write(f"{analyses_left()} of {FREE_ANALYSES} files left")        if st.button("Use my own key"):            key_dialog()st.markdown('<div class="vera-rule"></div>', unsafe_allow_html=True)if st.button("Reset session"):    for k in list(_defaults):        if k not in ("api_key",):            st.session_state[k] = _defaults[k]    st.rerun()tab1, tab2, tab3, tab4 = st.tabs(    ["1) Upload & Map", "2) Validate", "3) Explanations", "4) Export"])# ----------------------------------------------------------------------------# Tab 1 — Upload and map# ----------------------------------------------------------------------------with tab1:    st.subheader("Upload results file")    up = st.file_uploader("CSV or XLSX", type=["csv", "xlsx"])    demo_path = Path("prepared_samples/nist_prepared.csv")    c_demo, _ = st.columns([1, 3])    with c_demo:        if st.button("Load demo data", disabled=not demo_path.exists()):            st.session_state.source_bytes = demo_path.read_bytes()            st.session_state.last_filename = demo_path.name            st.session_state.analysis_counted = False            st.rerun()    if up is not None:        st.session_state.source_bytes = up.getvalue()        st.session_state.last_filename = up.name        st.session_state.analysis_counted = False    if st.session_state.source_bytes:        name = st.session_state.last_filename or "uploaded_file"        buf = io.BytesIO(st.session_state.source_bytes)        buf.name = name        df = load_table(buf)        st.session_state.df = df        st.caption(f"Loaded {name} · {len(df)} rows")        st.dataframe(preview(df))        headers = list(df.columns)        targets = required_metrics + required_meta        st.markdown("### Column mapping")        suggested, note = {}, ""        if ai_enabled():            if not st.session_state.analysis_counted:                record_analysis()                st.session_state.analysis_counted = True            with st.spinner("Matching columns"):                res = cached_mapping(tuple(headers), tuple(targets),                                     key_fingerprint())            record_call()            if res:                suggested = res.get("mapping", {})                note = res.get("notes", "")        if suggested:            st.caption(note or "Suggested by AI. Adjust anything that looks wrong.")        else:            suggested = suggest_mapping_fuzzy(headers, targets)            st.caption("Matched by name similarity. Adjust anything that looks wrong.")        mapping = {}        mcols = st.columns(min(3, max(1, len(targets))))        for i, m in enumerate(targets):            with mcols[i % len(mcols)]:                options = [""] + headers                guess = suggested.get(m, "")                idx = options.index(guess) if guess in options else 0                mapping[m] = st.selectbox(m, options=options, index=idx,                                          key=f"map_{m}")        st.session_state.mapping = mapping        st.markdown("### Units")        proposed = {m: tpl_units.get(m, "") for m in required_metrics}        if ai_enabled():            sample = {}            for m, h in mapping.items():                if h and m in required_metrics and h in df.columns:                    sample[m] = {"header": h,                                 "values": df[h].dropna().astype(str).tolist()[:5]}            if sample:                with st.spinner("Inferring units"):                    proposed = cached_units(json.dumps(sample, sort_keys=True),                                            json.dumps(tpl_units, sort_keys=True),                                            tuple(required_metrics),                                            key_fingerprint())                record_call()        units_map = {}        ucols = st.columns(min(4, max(1, len(required_metrics))))        for i, m in enumerate(required_metrics):            with ucols[i % len(ucols)]:                units_map[m] = st.text_input(m, value=proposed.get(m, ""),                                             key=f"unit_{m}")        st.session_state.units_map = units_map        st.success("Mapping and units captured. Open the Validate tab.")    with st.expander("Write a rule in plain English"):        nl = st.text_area(            "Describe your thresholds",            placeholder="tensile strength at least 55 MPa; "                        "elongation at break at least 8%; "                        "modulus between 1.5 and 3.5 GPa",            height=90,        )        if st.button("Generate template"):            if not ai_enabled():                key_dialog()            elif not nl.strip():                st.warning("Describe at least one threshold first.")            else:                system = (                    "Convert compliance rules into a compact YAML template for a "                    "validator. Use snake_case metric names such as tensile_strength, "                    "elongation_at_break, modulus. Include standard_id, version, "                    "units, and checks. Return YAML only, no commentary."                )                user = (                    f"Rules: {nl}\n"                    f"Preferred metric names: "                    f"{required_metrics or ['tensile_strength', 'elongation_at_break', 'modulus']}\n"                    "Check formats:\n"                    '- metric: tensile_strength\n  op: ">="\n  value: 55\n  unit: MPa\n'                    '- metric: modulus\n  op: "between"\n  min: 1.5\n  max: 3.5\n  unit: GPa\n'                )                try:                    with st.spinner("Writing YAML"):                        st.session_state.generated_yaml = complete(                            system, user, max_tokens=500)                    record_call()                except LLMUnavailable as e:                    st.error(f"Could not generate: {e}")        # Rendered outside the generate button so the adopt buttons survive a rerun.        if st.session_state.generated_yaml:            st.code(st.session_state.generated_yaml, language="yaml")            g1, g2 = st.columns(2)            with g1:                if st.button("Use this template"):                    try:                        st.session_state.template_override = parse_generated_yaml(                            st.session_state.generated_yaml)                        st.session_state.generated_yaml = None                        st.rerun()                    except Exception as e:                        st.error(f"Could not read that YAML: {e}")            with g2:                if st.button("Discard"):                    st.session_state.generated_yaml = None                    st.rerun()# ----------------------------------------------------------------------------# Validation# ----------------------------------------------------------------------------def run_validation(df: pd.DataFrame, mapping: dict, units_map: dict,                   template: dict) -> pd.DataFrame:    rename_map = {v: k for k, v in mapping.items() if v}    working = df.rename(columns=rename_map).copy()    rows = []    for idx, r in working.iterrows():        keys = set(rename_map.values()) | set(mapping.keys())        row_dict = {m: r.get(m, None) for m in keys}        specimen_id = str(r.get("specimen_id", idx))        lot_key = template.get("grouping", {}).get("lot_id", "lot")        lot = str(r.get(lot_key, r.get("lot", "")))        statuses, rationales = [], []        for chk in template.get("checks", []):            status, rationale = eval_check(row_dict, chk, units_map)            statuses.append(status)            rationales.append(rationale)        if all(s == "PASS" for s in statuses):            overall = "PASS"        elif any(s == "FAIL" for s in statuses):            overall = "FAIL"        elif any(s == "ERROR" for s in statuses):            overall = "ERROR"        else:            overall = "MISSING"        rows.append({"specimen_id": specimen_id, "lot": lot,                     "status": overall, "rationale": "; ".join(rationales)})    return pd.DataFrame(rows)def _show_table(styled):    try:        st.dataframe(styled, width="stretch")    except TypeError:        st.dataframe(styled, use_container_width=True)with tab2:    st.subheader("Run validation")    if st.session_state.df is None:        st.info("Upload a file in the first tab.")    else:        if st.button("Validate now"):            st.session_state.results_df = run_validation(                st.session_state.df, st.session_state.mapping,                st.session_state.units_map, template)        res = st.session_state.results_df        if res is not None:            counts = res["status"].value_counts()            k1, k2, k3, k4, k5 = st.columns(5)            k1.metric("Specimens", len(res))            k2.metric("Pass", int(counts.get("PASS", 0)))            k3.metric("Fail", int(counts.get("FAIL", 0)))            k4.metric("Missing", int(counts.get("MISSING", 0)))            k5.metric("Error", int(counts.get("ERROR", 0)))            palette = {                "PASS": "background-color:#E2EEDC; color:#27511F; font-weight:600;",                "FAIL": "background-color:#F5DFD9; color:#7E2817; font-weight:600;",                "MISSING": "background-color:#F4E8C9; color:#6A4E0B; font-weight:600;",                "ERROR": "background-color:#E7E3F0; color:#443066; font-weight:600;",            }            def _color(v):                return palette.get(str(v).upper(), "")            _show_table(res.style.map(_color, subset=["status"]))            if int(counts.get("ERROR", 0)):                st.warning("Some checks could not be evaluated. Usually a unit "                           "that could not be converted. Review the units above.")            st.success("Validation complete. Open the Explanations tab.")# ----------------------------------------------------------------------------# Explanations# ----------------------------------------------------------------------------with tab3:    st.subheader("Explain a specimen")    res = st.session_state.results_df    if res is None:        st.info("Run validation first.")    else:        failing = res.index[res["status"] != "PASS"].tolist()        default_idx = failing[0] if failing else 0        choice = st.selectbox("Specimen", options=list(res["specimen_id"]),                              index=int(default_idx))        row = res[res["specimen_id"] == choice].iloc[0]        checks_table = str(row["rationale"]).replace("; ", "\n")        st.code(checks_table, language="text")        used = len(st.session_state.explanations)        at_cap = used >= MAX_EXPLANATIONS and not visitor_key_set()        if st.button("Explain this specimen", disabled=at_cap):            if not ai_enabled():                key_dialog()            else:                with st.spinner("Writing explanation"):                    text = explain_specimen(std_id, std_ver, row["specimen_id"],                                            row.get("lot", ""), checks_table)                record_call()                text = enrich_with_playbook(row, text)                st.session_state.explanations[row["specimen_id"]] = text        if at_cap:            st.caption(f"{MAX_EXPLANATIONS} explanations per analysis on the "                       "shared key. Add your own key for more.")        if st.session_state.explanations:            st.markdown("### Saved explanations")            for sid, txt in st.session_state.explanations.items():                st.markdown(f"**{sid}**")                st.write(txt)# ----------------------------------------------------------------------------# Export# ----------------------------------------------------------------------------with tab4:    st.subheader("Export report")    res = st.session_state.results_df    if res is None:        st.info("Run validation first.")    else:        outname = st.text_input("Filename", value="ComplianceReport.pdf")        if st.button("Generate PDF"):            path = make_pdf(res, {"standard_id": std_id, "version": std_ver},                            st.session_state.explanations, out_path=outname)            if Path(path).exists():                with open(path, "rb") as f:                    st.download_button("Download report", data=f.read(),                                       file_name=outname,                                       mime="application/pdf")                st.success("Report ready.")            else:                st.error("Report generation failed.")